import { useEffect, useId, useRef, type SyntheticEvent } from "react";
import "./ConfirmDialog.css";

export interface ConfirmDialogProps {
  open: boolean;
  noteTitle: string;
  onCancel: () => void;
  onConfirm: () => void;
}

export function ConfirmDialog({ open, noteTitle, onCancel, onConfirm }: ConfirmDialogProps) {
  const dialogRef = useRef<HTMLDialogElement>(null);
  const cancelRef = useRef<HTMLButtonElement>(null);
  const titleId = useId();
  const bodyId = useId();

  // Keep the native <dialog> in step with the `open` prop. showModal() gives a
  // focus trap, inert page content and focus restoration on close.
  useEffect(() => {
    const dialog = dialogRef.current;
    if (!dialog) return;

    if (open && !dialog.open) {
      dialog.showModal();
      // Focus Cancel by default so an accidental Enter does not delete the note.
      cancelRef.current?.focus();
    } else if (!open && dialog.open) {
      dialog.close();
    }
  }, [open]);

  // Escape fires the native "cancel" event. Prevent the browser from closing the
  // dialog on its own, and let the parent decide by setting `open` to false.
  function handleCancelEvent(event: SyntheticEvent<HTMLDialogElement>) {
    event.preventDefault();
    onCancel();
  }

  return (
    <dialog
      ref={dialogRef}
      className="confirm-dialog"
      role="alertdialog"
      aria-labelledby={titleId}
      aria-describedby={bodyId}
      onCancel={handleCancelEvent}
    >
      <div className="confirm-dialog__body">
        <h2 id={titleId} className="confirm-dialog__title">
          Delete this note?
        </h2>
        <p id={bodyId} className="confirm-dialog__text">
          “{noteTitle}” will be removed. This cannot be undone.
        </p>
      </div>

      <div className="confirm-dialog__actions">
        <button
          ref={cancelRef}
          type="button"
          className="confirm-dialog__button confirm-dialog__button--quiet"
          onClick={onCancel}
        >
          Cancel
        </button>
        <button
          type="button"
          className="confirm-dialog__button confirm-dialog__button--primary"
          onClick={onConfirm}
        >
          Delete
        </button>
      </div>
    </dialog>
  );
}
```

