/* The dialog is hidden by the browser while closed. Only set layout under [open]
   so the UA rule for closed dialogs is not overridden. */
.confirm-dialog {
  box-sizing: border-box;
  width: min(90vw, 28rem);
  max-width: 100%;
  margin: auto;
  padding: clamp(1.25rem, 3vw, 1.75rem);
  border: 1px solid var(--hair);
  border-radius: 14px;
  background: var(--slide);
  color: var(--ink);
  font: inherit;
  font-size: clamp(0.95rem, 0.9rem + 0.2vw, 1.05rem);
  line-height: 1.5;
}

.confirm-dialog[open] {
  display: grid;
  gap: 1.25rem;
}

.confirm-dialog::backdrop {
  background: color-mix(in srgb, var(--slide) 70%, transparent);
}

.confirm-dialog__body {
  display: grid;
  gap: 0.5rem;
}

.confirm-dialog__title {
  margin: 0;
  font: inherit;
  font-size: clamp(1.1rem, 1rem + 0.5vw, 1.35rem);
  font-weight: 600;
  color: var(--ink);
}

.confirm-dialog__text {
  margin: 0;
  color: var(--muted);
  overflow-wrap: anywhere;
}

.confirm-dialog__actions {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 0.75rem;
}

.confirm-dialog__button {
  font: inherit;
  font-weight: 600;
  min-height: 2.75rem;
  padding: 0.5rem 1.25rem;
  border: 1px solid var(--ink);
  border-radius: 999px;
  background: transparent;
  color: var(--ink);
  cursor: pointer;
}

.confirm-dialog__button--quiet:hover {
  background: var(--myelin-wash);
}

.confirm-dialog__button--primary {
  border-color: var(--myelin);
  background: var(--myelin);
  color: var(--slide);
}

/* Motion is optional: animate only when the user has not asked for less. */
@media (prefers-reduced-motion: no-preference) {
  :root:not([data-motion="reduce"]) .confirm-dialog[open] {
    animation: confirm-dialog-in 180ms ease-out;
  }

  :root:not([data-motion="reduce"]) .confirm-dialog__button {
    transition: background-color 120ms ease-out;
  }
}

@keyframes confirm-dialog-in {
  from {
    opacity: 0;
    transform: translateY(8px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}
